#!/bin/bash
# Cuts the unit maps of the 19 new trio reference slots (g8trio: 18, g8trio2: hg003 slot 2) with
# consmapG8v4_fixdedup.py (U2) at the same settings (asm20, LO 2100, HI 2400, FRAG 5, PAD 100, CTX 200);
# run_rjf_trio.sh then joins them with the fix-1 map. Inputs new_rows.tsv / hap_seq_node_trio.tsv come from prep_canon_trio.sh.
# The commands run on the node.
# (a) G8 (unit map) and G6 maps for the 18 changed/new slots of new_rows.tsv
cd ~ && T=~/trio_v11 && [ ! -e $T/g8trio ] && [ ! -e $T/g6trio ] && mkdir -p $T/g8trio $T/g6trio && HSN=$T/hap_seq_node_trio.tsv CMPD=$T/cmp4d_trio WDIR=$T/g8trio TAG=trio PRESET=asm20 TH=8 LO=2100 HI=2400 FRAG=5 PAD=100 CTX=200 PYTHONIOENCODING=utf-8 python3 ~/consmapG8v4_fixdedup.py $T/new_rows.tsv > $T/g8trio/trio.out 2> $T/g8trio/trio.err; echo "G8 rc=$?"; tail -3 $T/g8trio/trio.out; ls $T/g8trio; HSN=$T/new_rows.tsv CMPD=$T/cmp4d_trio WDIR=$T/g6trio TAG=trio TH=8 PYTHONIOENCODING=utf-8 python3 ~/consmapG6_env.py 1 0 > $T/g6trio/trio.out 2> $T/g6trio/trio.err; echo "G6 rc=$?"; ls $T/g6trio; tail -3 $T/g6trio/trio.err

# (b) hg003 slot 2 := HG002 paternal array; writes hap_seq_node_trio2.tsv
#     (this command stops at `diff` under set -e, before cutting; (c) cuts the maps)
set -e; T=~/trio_v11; C=$T/cmp4d_trio; N=trioinf__58__hiarr_hg002_3_as_hg003_2.fa; [ -e $C/$N ] && { echo already; exit 1; }; cp ~/hiasm/arr/hiarr_hg002_3.fa $C/$N; cmp -s ~/hiasm/arr/hiarr_hg002_3.fa $C/$N && echo "copy identical $(md5sum < $C/$N | cut -c1-8)"; echo "Q100 paternal sequence identity check: $(tail -n +2 ~/asmarr/arr_HG002_1.fa | tr -d "\n" | md5sum | cut -c1-8) vs $(tail -n +2 $C/$N | tr -d "\n" | md5sum | cut -c1-8)"; [ -e $T/hap_seq_node_trio2.tsv ] && exit 1; awk -F"\t" -v n=$N "BEGIN{OFS=\"\t\"} \$1==\"hg003\" && \$2==\"2\" {\$3=n} {print}" $T/hap_seq_node_trio.tsv > $T/hap_seq_node_trio2.tsv; diff $T/hap_seq_node_trio.tsv $T/hap_seq_node_trio2.tsv; printf "hg003\t2\t$N\n" > $T/new_rows2.tsv; mkdir $T/g8trio2 $T/g6trio2; cd ~; HSN=$T/hap_seq_node_trio2.tsv CMPD=$C WDIR=$T/g8trio2 TAG=trio2 PRESET=asm20 TH=8 LO=2100 HI=2400 FRAG=5 PAD=100 CTX=200 PYTHONIOENCODING=utf-8 python3 ~/consmapG8v4_fixdedup.py $T/new_rows2.tsv > $T/g8trio2/o.txt 2> $T/g8trio2/e.txt; HSN=$T/new_rows2.tsv CMPD=$C WDIR=$T/g6trio2 TAG=trio2 TH=8 python3 ~/consmapG6_env.py 1 0 > /dev/null 2>&1; cut -f1-8 $T/g8trio2/CONSENSUS_SUM_G8_trio2.tsv; cut -f1-9 $T/g6trio2/sum_trio2.tsv; echo "G8 hg002 slot2 row and variant column comparison:"; diff <(awk -F"\t" "\$1==\"hg002\"&&\$2==\"2\"" $T/g8trio/CONSENSUS_MAP_G8_trio.tsv | cut -f4-) <(awk -F"\t" "\$1==\"hg003\"&&\$2==\"2\"" $T/g8trio2/CONSENSUS_MAP_G8_trio2.tsv | cut -f4-) | wc -l

# (c) G8/G6 maps for hg003 slot 2 (19th slot)
T=~/trio_v11; C=$T/cmp4d_trio; N=trioinf__58__hiarr_hg002_3_as_hg003_2.fa; [ -e $T/new_rows2.tsv ] || printf "hg003\t2\t$N\n" > $T/new_rows2.tsv; [ -e $T/g8trio2 ] && { echo g8trio2 present; exit 1; }; mkdir $T/g8trio2 $T/g6trio2; cd ~; HSN=$T/hap_seq_node_trio2.tsv CMPD=$C WDIR=$T/g8trio2 TAG=trio2 PRESET=asm20 TH=8 LO=2100 HI=2400 FRAG=5 PAD=100 CTX=200 PYTHONIOENCODING=utf-8 python3 ~/consmapG8v4_fixdedup.py $T/new_rows2.tsv > $T/g8trio2/o.txt 2> $T/g8trio2/e.txt; HSN=$T/new_rows2.tsv CMPD=$C WDIR=$T/g6trio2 TAG=trio2 TH=8 python3 ~/consmapG6_env.py 1 0 > /dev/null 2>&1; cut -f1-8 $T/g8trio2/CONSENSUS_SUM_G8_trio2.tsv; cut -f1-9 $T/g6trio2/sum_trio2.tsv; echo "G8 row comparison(hg002 slot2 vs hg003 slot2, from column 4) differing lines: $(diff <(awk -F"\t" "\$1==\"hg002\"&&\$2==\"2\"" $T/g8trio/CONSENSUS_MAP_G8_trio.tsv | cut -f4-) <(awk -F"\t" "\$1==\"hg003\"&&\$2==\"2\"" $T/g8trio2/CONSENSUS_MAP_G8_trio2.tsv | cut -f4-) | wc -l)"
